							$scope.getmedicationDetails = function(medication) {
								if(medication.length < 3) {
									$scope.showMedicationOptions = false
									return
								}
								var unitId = $scope.unitId
								var orgId = $scope.organizationId
								var regex=/[^a-z]/gi;
								medication=medication.replace(regex," ");
								
								var URI = BASE_URL + ROOT_URL + GETMEDICATIONDETAILS + "?unitId=" + 
									unitId + "&orgId=" + orgId + "&searchDrug=" + medication
								
								GenericServiceParamHeader.serviceAction(METHOD_GET, URI).then(function(response) {
									if(response.data.status == "success"){
										if(response.data.listObject.length !== 0) {
											$scope.showMedicationOptions = true
											$scope.drugOptions = []
											var responseList = response.data.listObject
											for(var i = 0; i< responseList.length; i++) {
												var medicationDetailsObj = {}
												medicationDetailsObj["medicationName"] = responseList[i].medicationName
												medicationDetailsObj["genericName"] = responseList[i].genericName
												// medicationDetailsObj["roa_options"]
												// =
												// responseList[i].roaMasterDtoList
												medicationDetailsObj["formulationTypeId"] = responseList[i].formulationTypeId
												medicationDetailsObj["favorite_status"] = false
												$scope.drugOptions.push(medicationDetailsObj)
											}
										}
									}
								})
							}
							
